<template>
  <div class="flex gap-4 flex-col">
    <div
      v-if="!isPublic && (fallbackTo || (isAdmin && subject === 'project'))"
      class="flex gap-2 items-center flex-wrap justify-between w-full"
    >
      <!-- Gated on fallbackTo (not journey parent) on purpose: dashboards without a
           fallback (e.g. system dashboard) never show a back button, matching pre-journey behavior -->
      <GoBackButton v-if="fallbackTo" :subject="subject" :fallback-to="fallbackTo" />
      <PublicLinkDialog v-if="isAdmin && subject === 'project'" subject="dashboard" />
    </div>
    <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 2xl:grid-cols-4 gap-4">
      <slot />
    </div>
    <DashboardLastUpdated v-if="calculatedAt" :calculated-at="calculatedAt" />
  </div>
</template>

<script setup lang="ts">
import type { TypedNuxtLink } from '#build/typed-router/typed-router';

const { isAdmin } = useUserRole();

interface Props {
  fallbackTo?: TypedNuxtLink['to'];
  calculatedAt?: string | null;
  subject: 'project' | 'user' | 'system';
  isPublic?: boolean;
}

defineProps<Props>();
</script>
